-- Run ONLY in an isolated scratch database, followed by the migration under test.
create table public.award_orders (id uuid primary key, status text, award_payment_status text, award_paid_at timestamptz, award_paid_attempt_id uuid, paid_at timestamptz,paystack_reference text,paystack_status text);
create table public.award_payment_attempts(id uuid primary key,order_id uuid,provider text,charge_scope text,status text,captured_amount_minor bigint,requested_amount_minor bigint,currency text,award_coupon_id uuid);
create table public.award_delivery_orders(id uuid primary key,order_id uuid,member_id uuid,status text,quote_input jsonb,resolved_delivery jsonb,carrier_quote jsonb,amount_minor bigint,currency text,expires_at timestamptz,reference text,checkout_id text unique,checkout_url text,checkout_expires_at timestamptz,checkout_request text,charge_id text unique,paid_at timestamptz,payment_evidence jsonb,booking_started_at timestamptz,waybill text,tracking_url text,booking_response jsonb,created_at timestamptz default now());
